      "examples": [
        {
          "de": "Die Ärztin berät den Patienten.",
          "lv": "The doctor advises the patient."
        },
        {
          "de": "Wir beraten über den Plan.",
          "lv": "We are discussing the plan."
        },
        {
          "de": "Die Eltern beraten sich mit der Lehrerin.",
          "lv": "The parents are consulting the teacher."
        }
      ],
